<script lang="ts">import Icon from './Icon.svelte';let {code,filename}:{code:string,filename?:string}=$props();let copied=$state(false);async function copy(){await navigator.clipboard.writeText(code);copied=true;setTimeout(()=>copied=false,1200)}</script>
<div class="overflow-hidden rounded-md border bg-code text-code-foreground"><div class="flex h-9 items-center border-b border-white/10 px-3 font-mono text-[11px] text-white/55"><span>{filename??'Terminal'}</span><button onclick={copy} class="ml-auto inline-flex items-center gap-1.5 hover:text-white"><Icon name="copy" class="size-3"/>{copied?'Kopiert':'Kopieren'}</button></div><pre class="overflow-x-auto p-4 text-[13px] leading-6"><code>{code}</code></pre></div>
